goal.statement:
let X := fun x => ↑(↑(f x) + 1);
let μ := (PMF.uniformOfFintype V).toMeasure;
MeasureTheory.integral μ X = (↑n + 1) ^ 2 / (2 * ↑n + 1) ∧
  ProbabilityTheory.variance X μ = (↑n ^ 4 + 2 * ↑n ^ 3 + 2 * ↑n ^ 2 + ↑n) / (3 * (2 * ↑n + 1) ^ 2)

